function reverseTwice(arr) {
  return [...arr].reverse().reverse();
}

const testCases = [[1, 2, 3], [], ['a'], [5, 5, 5, 1]];

const allPass = testCases.every(
  (arr) => JSON.stringify(reverseTwice(arr)) === JSON.stringify(arr)
);

console.log(allPass);

